// UI-only integration simulation. No requests are sent to an external DOX AI API.
let doxInbox=null,doxInboxFilter='all',doxSelectedId=null,doxRejectId=null;
function createGeneratedDoxInbox(){const now=new Date(),spec=[['복합기 임대 및 유지보수 계약','프린트솔루션',15000000],['문서관리 서버 구매 계약','한빛테크놀로지',28000000],['통합 보안 솔루션 도입 계약','네오시큐리티',42000000]];return spec.map(([title,supplier,supply],i)=>{const r=blank();r.id=`d0a1000${i+1}-0000-4000-9000-00000000000${i+1}`;r.title=title;r.type='구매·계약';r.owner=['이담당','김담당','박담당'][i];r.memo='DOX AI 전송·승인 흐름 시연용 가상 구매계약입니다. 실제 거래가 아닙니다.';r.method='excel';r.fileName=`DOX_AI_수신결과_${String(i+1).padStart(3,'0')}.json`;r.status='registered';r.isDemo=true;Object.assign(r.values,{project_name:title,ordering_organization:'Fuji ERP 데모 조직',ordering_department:['총무부','정보기술부','정보보안부'][i],ordering_contact:r.owner,delivery_location:'Fuji ERP 데모 본사',bidding_method:'수의계약',supplier_name:supplier,supplier_contact:'demo@example.com',supplier_representative:'데모 대표자',bid_notice_number:`DEMO-DOX-BID-${i+1}`,award_notice_number:`DEMO-DOX-AWARD-${i+1}`,contract_number:`DEMO-DOX-CONTRACT-${i+1}`,purchase_order_number:`DEMO-DOX-PO-${i+1}`,inspection_number:`DEMO-DOX-CHECK-${i+1}`,tax_invoice_number:`DEMO-DOX-TAX-${i+1}`,transaction_statement_number:`DEMO-DOX-STATEMENT-${i+1}`,total_amount:String(supply+supply/10),supply_amount:String(supply),vat_amount:String(supply/10),inspection_date:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(now),deliverables:title+' 관련 장비·소프트웨어 및 납품 확인서',proposal_summary:'DOX AI가 전송한 구매계약 정보로 가정한 데모 데이터입니다. 승인 시 ERP에 등록되며 반려 시 수신함에 사유를 보관합니다.'});return {id:'DOX-DEMO-'+String(i+1).padStart(3,'0'),status:'pending',receivedAt:new Date(now.getTime()-i*12*60000).toISOString(),processedAt:null,rejectReason:'',erpRecordId:null,record:r};});}
function createBidDocumentReceipt(){const r=blank();r.id="d0a10004-0000-4000-9000-000000000004";r.title=BID_DOCUMENT_VALUES.project_name;r.type="구매·계약";r.owner=BID_DOCUMENT_VALUES.ordering_contact;r.memo="첨부 Excel의 수신 정보와 사업자 기본정보 확인서 PDF를 함께 확인하는 건입니다.";r.method="excel";r.fileName="DoxAI_Test01_Bid-Related Documents.xlsx";r.status="registered";r.values={...BID_DOCUMENT_VALUES};r.attachments=[{name:"businessregistrationD1.pdf",url:"assets/documents/businessregistrationD1.pdf",preview:"assets/documents/businessregistrationD1-preview.png",type:"application/pdf",pages:1}];return {id:"DOX-BID-004",status:"pending",receivedAt:new Date().toISOString(),processedAt:null,rejectReason:"",erpRecordId:null,sourceWorkbook:r.fileName,attachments:r.attachments,record:r};}
function createDoxInbox(){return [createBidDocumentReceipt(),...createGeneratedDoxInbox()];}
function ensureDoxInbox(){if(!Array.isArray(doxInbox)){doxInbox=createDoxInbox();return;}const defaults=createDoxInbox();for(const d of defaults){if(!doxInbox.some(x=>x.id===d.id))doxInbox.push(d);}doxInbox=doxInbox.filter(x=>x&&x.id&&x.record?.values&&['pending','approved','rejected'].includes(x.status));const doc=doxInbox.find(x=>x.id==='DOX-BID-004');if(doc)doxInbox=[doc,...doxInbox.filter(x=>x.id!==doc.id)];}
function refreshDoxBadge(){const n=(doxInbox||[]).filter(x=>x.status==='pending').length;$('#doxPendingBadge').textContent=n;$('#doxPendingBadge').hidden=!n;}
function doxStatusLabel(status){return {pending:'승인 대기',approved:'승인 완료',rejected:'반려'}[status];}
function renderDoxDocument(item){const pdf=item.attachments?.find(a=>a.type==='application/pdf');$('#doxDocumentPanel').hidden=!pdf;$('#doxReviewLayout').classList.toggle('has-document',!!pdf);$('#doxSourceCaption').textContent=item.sourceWorkbook||item.record.fileName||'';if(!pdf){$('#doxPdfPreview').removeAttribute('src');$('#doxPdfOpen').removeAttribute('href');$('#doxPdfDownload').removeAttribute('href');return;}$('#doxDocumentName').textContent=pdf.name;$('#doxPdfOpen').href=pdf.url;$('#doxPdfDownload').href=pdf.url;$('#doxPdfPreview').src=pdf.preview;}
function renderDoxInbox(){ensureDoxInbox();refreshDoxBadge();const pending=doxInbox.filter(x=>x.status==='pending').length,approved=doxInbox.filter(x=>x.status==='approved').length,rejected=doxInbox.filter(x=>x.status==='rejected').length;$('#doxInboxStats').innerHTML=[['수신 건',doxInbox.length,'all'],['승인 대기',pending,'pending'],['승인 완료',approved,'approved'],['반려',rejected,'rejected']].map(([label,n,status])=>`<div class="dox-stat ${status}"><span>${label}</span><strong>${n}<small>건</small></strong></div>`).join('');const visible=doxInbox.filter(x=>doxInboxFilter==='all'||x.status===doxInboxFilter);$('#doxInboxBody').innerHTML=visible.length?visible.map(x=>{const r=x.record,linked=records.find(r=>r.id===x.erpRecordId);return `<tr><td><small>${esc(x.id)}</small><button class="dox-item-title" data-dox-detail="${x.id}">${esc(r.title)}</button>${x.attachments?.length?`<button class="dox-pdf-chip" data-dox-detail="${x.id}">▧ 첨부 PDF 보기</button>`:''}<span class="dox-item-owner">담당자 ${esc(r.owner)}</span></td><td>${esc(r.values.supplier_name)}</td><td class="dox-money">${esc(money(r.values.total_amount))}</td><td class="dox-date">${esc(time(x.receivedAt))}</td><td><span class="dox-status ${x.status}">${doxStatusLabel(x.status)}</span>${x.processedAt?`<small class="dox-processed">${esc(time(x.processedAt))}</small>`:''}</td><td><div class="dox-row-actions">${x.status==='pending'?`<button class="dox-approve" data-dox-approve="${x.id}">승인</button><button class="dox-reject" data-dox-reject="${x.id}">반려</button>`:x.status==='approved'?linked&&!linked.deletedAt?`<button class="dox-view" data-dox-view="${x.erpRecordId}">ERP에서 보기 ↗</button>`:'<span class="dox-deleted-note">ERP 건이 휴지통에 있습니다.</span>':`<button class="dox-view" data-dox-detail="${x.id}">반려 사유 보기</button>`}</div></td></tr>`;}).join(''):'<tr><td colspan="6" class="dash-empty">해당 상태의 수신 건이 없습니다.</td></tr>';$('#doxInboxBody').querySelectorAll('[data-dox-detail]').forEach(b=>b.onclick=()=>{showDoxDetail(b.dataset.doxDetail);$('#doxDetailPanel').scrollIntoView({block:'start',behavior:'smooth'});});$('#doxInboxBody').querySelectorAll('[data-dox-approve]').forEach(b=>b.onclick=()=>approveDoxItem(b.dataset.doxApprove));$('#doxInboxBody').querySelectorAll('[data-dox-reject]').forEach(b=>b.onclick=()=>openDoxReject(b.dataset.doxReject));$('#doxInboxBody').querySelectorAll('[data-dox-view]').forEach(b=>b.onclick=()=>{$('#doxInboxDialog').close();navigate('#case/'+b.dataset.doxView);});if(doxSelectedId)showDoxDetail(doxSelectedId);}
function showDoxDetail(id){const item=doxInbox.find(x=>x.id===id);if(!item)return;doxSelectedId=id;$('#doxDetailPanel').hidden=false;renderDoxDocument(item);$('#doxDetailTitle').textContent=item.record.title;$('#doxDetailBody').innerHTML=SCHEMA.map(f=>`<tr><td>${esc(f.label)}</td><td>${esc(f.type==='number'?money(item.record.values[f.key]):item.record.values[f.key]||'미입력')}</td></tr>`).join('');$('#doxDecisionInfo').textContent=item.status==='rejected'?'반려 사유: '+item.rejectReason:item.status==='approved'?'승인 완료 · ERP 구매·계약 목록에 등록되었습니다.':item.sourceWorkbook?'승인 대기 · 첨부 문서와 수신 정보를 확인해 주세요.':'승인 대기 · 아래 정보는 DOX AI가 전송한 것으로 가정한 더미 값입니다.';$('#doxDecisionInfo').className='dox-decision-info '+item.status;}
function approveDoxItem(id){const item=doxInbox?.find(x=>x.id===id);if(!item||item.status!=='pending')return false;const existing=records.find(r=>r.sourceInboxId===id||r.id===item.record.id),approved=copy(item.record),now=new Date().toISOString();approved.status='registered';approved.createdAt=now;approved.updatedAt=now;approved.registrationId='ERP-DOX-DEMO-'+id.slice(-3);approved.sourceInboxId=id;approved.approvalSource='dox-demo';if(validate(approved).length){toast('수신 정보의 필수 항목을 확인해 주세요.');return false;}const nextRecords=existing?records:[approved,...records],previous=doxInbox;doxInbox=doxInbox.map(x=>x.id===id?{...x,status:'approved',processedAt:now,erpRecordId:existing?.id||approved.id}:x);if(!storeData(nextRecords)){doxInbox=previous;toast('승인 결과를 브라우저에 저장하지 못했습니다.');return false;}records=nextRecords;renderList();renderDashboard();renderDoxInbox();toast('승인했습니다. ERP 구매·계약 목록에 등록되었습니다.');return true;}
function openDoxReject(id){const item=doxInbox.find(x=>x.id===id&&x.status==='pending');if(!item)return;doxRejectId=id;$('#doxRejectTitle').textContent=item.record.title;$('#doxRejectReason').value='';$('#doxRejectDialog').showModal();$('#doxRejectReason').focus();}
function rejectDoxItem(id,reason){const item=doxInbox?.find(x=>x.id===id);if(!item||item.status!=='pending')return false;reason=String(reason||'').trim();if(!reason){toast('반려 사유를 입력해 주세요.');$('#doxRejectReason').focus();return false;}const previous=doxInbox;doxInbox=doxInbox.map(x=>x.id===id?{...x,status:'rejected',rejectReason:reason.slice(0,500),processedAt:new Date().toISOString()}:x);if(!storeData()){doxInbox=previous;toast('반려 결과를 브라우저에 저장하지 못했습니다.');return false;}renderDoxInbox();toast('반려했습니다. 사유를 수신함에 보관했습니다.');return true;}
function setupDoxInbox(){$('#connectDox').onclick=()=>{doxInboxFilter='all';doxSelectedId=null;$('#doxDetailPanel').hidden=true;document.querySelectorAll('[data-dox-filter]').forEach(b=>b.classList.toggle('active',b.dataset.doxFilter==='all'));renderDoxInbox();$('#doxInboxDialog').showModal();};$('#closeDoxInbox').onclick=()=>$('#doxInboxDialog').close();$('#finishDoxInbox').onclick=()=>$('#doxInboxDialog').close();$('#closeDoxDetail').onclick=()=>{doxSelectedId=null;$('#doxDetailPanel').hidden=true;};document.querySelectorAll('[data-dox-filter]').forEach(b=>b.onclick=()=>{doxInboxFilter=b.dataset.doxFilter;document.querySelectorAll('[data-dox-filter]').forEach(x=>x.classList.toggle('active',x===b));renderDoxInbox();});for(const id of ['closeDoxReject','cancelDoxReject'])$('#'+id).onclick=()=>$('#doxRejectDialog').close();$('#confirmDoxReject').onclick=()=>{if(rejectDoxItem(doxRejectId,$('#doxRejectReason').value)){$('#doxRejectDialog').close();doxRejectId=null;}};}
